assert($VM('.env', '.env.aaa') < 0, 'dotfiles with the same root sort shortest first');
        // dotfile vs non-dotfile comparisons
        assert($VM(null, '.abc') < 0, 'null should come before dotfiles');
        assert($VM('.env', 'aaa.env') < 0, 'dotfiles come before filenames with extensions');
        assert($VM('.MD', 'a.md') < 0, 'dotfiles sort before lowercase files');
        assert($VM('.env', 'aaa') < 0, 'dotfiles come before filenames without extensions');
        assert($VM('.md', 'A.MD') < 0, 'dotfiles sort before uppercase files');
        // numeric comparisons
        assert($VM('1', '1') === 0, 'numerically equal full names should be equal');
        assert($VM('abc1.txt', 'abc1.txt') === 0, 'equal filenames with numbers should be equal');
        assert($VM('abc1.txt', 'abc2.txt') < 0, 'filenames with numbers should be in numerical order, not alphabetical order');
        assert($VM('txt.abc1', 'txt.abc1') === 0, 'equal extensions with numbers should be equal');
